const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const required=Array.isArray(input.required_evidence)?input.required_evidence:[];
const verified=Array.isArray(input.verified_evidence)?input.verified_evidence:[];
const failed=Array.isArray(input.failed_evidence)?input.failed_evidence:[];
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const executionIdentity=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const executedAgreement=Boolean(input.executed_agreement||input.signature_executed===true||["signed","executed","completed"].includes(String(input.signature_status||"").toLowerCase()));
const verifiedSet=new Set(verified.map(v=>String(typeof v==="string"?v:v.type||v.name||"").toLowerCase()).filter(Boolean));
const missing=required.filter(v=>!verifiedSet.has(String(typeof v==="string"?v:v.type||v.name||"").toLowerCase()));
const milestonesComplete=milestones.length>0&&milestones.every(m=>["completed","complete","done"].includes(String(m.status||"").toLowerCase()));
let status="blocked",nextWorkflow="WF-126",reason="";
if(blockers.length){reason="active blockers prevent final closing completion";}
else if(!executionIdentity){status="identity_incomplete";reason="deal/lead/property identity is incomplete";}
else if(!executedAgreement){status="execution_evidence_missing";nextWorkflow="WF-302";reason="executed agreement evidence is missing";}
else if(failed.length||missing.length){status="evidence_incomplete";nextWorkflow="WF-306";reason="required closing evidence is incomplete or failed";}
else if(!milestonesComplete){status="completion_incomplete";nextWorkflow="WF-305";reason="closing milestones are not fully complete";}
else{status="closing_outcome_ready";nextWorkflow="WF-308";reason="closing evidence, execution identity, and milestones reconcile; final close verification is ready";}
const idempotencyKey=input.idempotency_key||`wf-307:${input.deal_id||"unknown"}:${input.close_version||input.version||1}`;
return [{json:{...input,workflow:"WF-307",workflow_name:"Reconciled Closing Evidence → Final Closing Outcome & Completion Controller",status,final_closing_outcome:{execution_identity_ready:executionIdentity,executed_agreement_verified:executedAgreement,required_evidence_count:required.length,verified_evidence_count:verified.length,missing_evidence:missing,failed_evidence_count:failed.length,milestones_complete:milestonesComplete,blockers},next_workflow:nextWorkflow,human_review_required:status!=="closing_outcome_ready",audit:{event_type:"final_closing_outcome",idempotency_key:idempotencyKey,reason}}}];
